"""out/head_report.md from the checks result (no numbers are typed here: everything comes from checks.json)."""
from __future__ import annotations

from . import hp as H
from .geom import OUT


def _t(head, rows):
    out = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def write(res):
    d = res["data"]
    md = ["# Detector head -- check and calculation report", "",
          f"Generated by `mechanical/head/checks.py` (contract {res['contract_version']}). Evidence classes: **tool-checked** = evaluated on the CadQuery solids; "
          "**calculated** = closed-form model with stated assumptions; nothing here is measured. Summary: "
          f"{res['summary']['pass']} pass, {res['summary']['fail']} fail, {res['summary']['deviation']} deviation (decision needed).", "",
          "## 1. Checks", "", _t(["Check", "Status", "Evidence", "Detail"], [(c["check"], c["status"].upper(), c["evidence"], (c["detail"] if len(str(c["detail"])) < 700 else str(c["detail"])[:700] + " ...")) for c in res["checks"]]), ""]
    md += ["## 2. Deviations that need the lead's decision", ""]
    md += [f"- **{c['check']}** -- {c['detail']}" for c in res["checks"] if c["status"] == "deviation"]
    md += ["", "## 3. Mass and centre of gravity (calculated from model volumes and handbook densities; OEM modules assumed)", ""]
    rows = []
    for b in ("prototype", "production", "dummy"):
        m = d[f"mass_{b}"]
        rows.append((b, m["mass_g"], " / ".join(f"{v:.1f}" for v in m["cg_mm"]), m["mass_without_pigtails_g"], " / ".join(f"{v:.1f}" for v in m["cg_without_pigtails_mm"])))
    md += [_t(["Build", "Mass (g)", "CG x / y / z (mm, base_link)", "Mass without pigtails (g)", "CG without pigtails"], rows), "",
           f"Dummy head: steel ballast plate {d['dummy_ballast_mm']} mm per lane (thickness solved so that the mass matches the prototype head).", "",
           "Largest items, prototype (g): " + ", ".join(f"{k} {v}" for k, v in d["mass_prototype"]["largest_items_g"].items()), ""]
    md += ["## 4. Deflection under 20 N at the front outer window corner and first modes (calculated)", "",
           "Model: rigid-body pitch on the four receiver lands (lead's mount model C, same contact stiffness assumption), roll through a two-halves model (each half on its own shoe, "
           "joined at y = 0 by the listed bridging members), wing bending and wing twist of the 47.75 mm overhang beyond the T-head. The lid is a shear panel: 35 M3 screws round a closed loop at <= 40 mm pitch, 17 into M3 standoffs on the spreader (bending stiffness 20 % of fixed-fixed, "
           "STATED ASSUMPTION) and 18 into hard bosses on the frame walls (1500 N/mm per printed-insert joint, 8000 N/mm tapped aluminium, STATED ASSUMPTION); the weaker fastener row is the shear web of the closed cell. Lid-off values show what the cover contributes.", ""]
    rows = []
    for k, v in d["structure"].items():
        a, b = v["lid fitted (all screws)"], v["lid removed (service state)"]
        rows.append((k, f"{v['mass_kg']:.2f}", f"{a['pitch']:.3f}", f"{a['roll_incl_joint']:.3f}", f"{a['wing_bending']:.3f}", f"{a['wing_twist']:.3f}", f"**{a['total']:.2f}**", f"{b['total']:.2f}",
                     f"{v['roll_if_joint_rigid']:.3f}", f"{a['k_joint_Nm_per_rad']:.0f}", f"{v['f1_hz']:.0f}"))
    md += [_t(["Case", "Mass (kg)", "Pitch (mm)", "Roll incl. joint (mm)", "Wing bending (mm)", "Wing twist (mm)", "Total, lid on (mm)", "Total, lid off (mm)", "Roll if joint rigid (mm)",
               "Joint stiffness (N m/rad)", "First mode (Hz)"], rows), ""]
    k0 = next(iter(d["structure"].values()))
    md += ["Members crossing the y = 0 joint (N m/rad, prototype): " + "; ".join(f"{k} {v:.0f}" for k, v in k0["joint_terms_Nm_per_rad"].items()) + ".", "",
           "Modes (Hz): " + "; ".join(f"{name}: " + ", ".join(f"{m} {f:.0f}" for m, f in v["modes_hz"].items()) for name, v in d["structure"].items()), "",
           "**Reading.** The joint is outside the primary load path only for symmetric loads; a corner load is shared by both shoes through the members that cross y = 0. "
           "With the one-piece spreader, the lid coupled through the standoffs and the aluminium rear bridge the joint adds little to the corner deflection (compare the 'roll if joint rigid' column), "
           "so **full-width stiffening rods are not needed**; with the lid removed the head is still inside the 1.0 mm acceptance limit of the gap method but must not be used for gap measurements. "
           "All values scale with the assumed land stiffness (1500 / 6000 N/mm per land) -> prove with the 20 N corner test.", ""]
    r = d["rails"]
    f, s = r["front"], r["side"]
    md += ["## 5. Contact rails (calculated; switch data PARTIAL)", "",
           _t(["Quantity", "Leading rail (front zone)", "Side zones (left, right)"], [
               ("Travel to the positive stop", f"{f['stroke_to_stop_mm']:.1f} mm (bar on the frame front face, load into the front wall)", f"{s['travel_to_stop_lateral_mm']:.2f} mm lateral (strip on the side wall), slide {s['slide_travel_mm']:.2f} mm at 45 deg"),
               ("Trip travel min / nominal / max", " / ".join(f"{v:.2f}" for v in f["trip_travel_mm"].values()) + " mm", " / ".join(f"{v:.2f}" for v in s["trip_lateral_mm"].values()) + " mm"),
               ("Stroke after trip", f"{f['post_trip_stroke_mm']:.1f} mm (requirement >= 15)", f"{s['margin_trip_before_stop_mm']:.2f} mm (envelope-limited: 3.75 mm outer margin)"),
               ("Switch plunger at the stop / available", f"{f['plunger_depression_at_stop_mm']:.2f} / {f['plunger_travel_available_mm']:.1f} mm (cam dwell)", f"{s['plunger_depression_at_stop_mm']:.2f} / {s['plunger_travel_available_mm']:.1f} mm"),
               ("Return force", f"{f['spring_force_N']['rest (both)']:.1f} N at rest, {f['spring_force_N']['full stroke (both)']:.1f} N at the stop; trip force about {f['trip_force_N_estimate']:.1f} N", "one 2 N spring per zone on the diagonal (estimate)"),
               ("Anti-racking", f"bail: far end lags {f['bail']['lag_of_far_end_mm_for_end_hit']:.2f} mm for a hit on one end ({f['bail']['sync_stiffness_N_per_mm_differential']:.0f} N/mm differential); arm {f['bail']['arm_angle_rest_deg']:.0f} -> {f['bail']['arm_angle_full_deg']:.0f} deg", "single 45 deg slide on three pins"),
               ("Speed that stops inside the post-trip stroke", "; ".join(f"{k}: {v:.3f} m/s" for k, v in f["max_speed_stopping_inside_post_trip_stroke_mps"].items()), "-"),
           ]), "",
           f"Travel after contact at 0.10 m/s from mech_calcs.md section 8: {f['stop_model_mm']}. The {f['post_trip_stroke_mm']:.1f} mm stroke covers the electronics-model value with margin and "
           "not the contract-input value (27.5 mm): the remaining distance is the 7 mm between the frame front face and the window edge (rigid frame, no optics loaded) plus the speed limit near obstacles.", "",
           f"Switch data used: {r['switch_data']}", "",
           (lambda q: f"**Leading rail front face (tool-checked):** unloaded x {q['unloaded_x']:.1f}, fully stroked (bar on the frame face) x {q['full_stroke_x']:.1f}; "
                      f"end-wall residual strip from the window front edge (x {q['window_front_edge_x']:.1f}) to the rail face {q['residual_strip_unloaded_mm']:.1f} mm unloaded, "
                      f"{q['residual_strip_full_stroke_mm']:.1f} mm stroked. Contract draft6 envelope x [66.0, 212.5].")(d["rail_front_face"]), ""]
    md += ["## 6. Light-path analysis of every joint (analysis of the model geometry, not a light test)", "",
           _t(["Id", "Joint", "From", "To", "Path", "Length (mm)", "Turns", "Barriers", "Builds"],
              [(x["id"], x["joint"], x["from"], x["to"], x["path"], f"{x['length_mm']:.1f}", x["turns"], x["barriers"], x["builds"]) for x in d["light_paths"]]), "",
           "Split joint result (L01, L02): ambient-to-bay path 5.4 mm long with 4 right-angle turns through the U tongue-and-groove, closed at both ends by the lid gasket; "
           "no path from the joint plane into a lane (3.25 mm solid half ribs, 1.45 mm at the groove).", ""]
    t = d["tolerance_stack"]
    md += ["## 7. Tolerance stack: head contribution to the film-to-floor gap (datum C to film plane, calculated)", "",
           _t(["Contributor", "Nominal (mm)", "Prototype +- (mm)", "Production +- (mm)", "Note"], [(x["contributor"], f"{x['nominal_mm']:+.2f}", f"{x['prototype_pm']:.3f}", f"{x['production_pm']:.3f}", x["note"]) for x in t["rows"]]), "",
           f"Film plane nominal z = {t['nominal_film_z']:.2f}. Prototype: +-{t['prototype']['worst_case_pm_mm']:.2f} mm worst case, +-{t['prototype']['rss_pm_mm']:.2f} mm RSS. "
           f"Production: +-{t['production']['worst_case_pm_mm']:.2f} / +-{t['production']['rss_pm_mm']:.2f} mm. Budget line in mech_calcs.md section 6: +-{t['budget_line_in_mech_calcs_pm_mm']:.2f} mm.", ""]
    md += ["## 8. Dimensions that depend on the missing OEM drawing", "", _t(["OEM quantity (assumption)", "Head dimension it drives", "How the housing absorbs a different value"], [(x["oem_quantity"], x["head_dimension"], x["adjustment"]) for x in d["oem_dependent"]]), ""]
    th = {k: v for k, v in d["thermal"].items() if not k.startswith("_")}
    cov = d["thermal"]["_jacket_coverage"]
    md += ["## 9. Thermal: heater power with and without the standard insulating jacket (calculated, lumped; same coefficients as mech_calcs.md section 7)", "",
           f"Assumptions: steady state; outside film 12 W/m2K (still air) / 25 W/m2K (3 m/s draught), inside 6, floor-facing side 8 W/m2K; foam k 0.035, printed PA-CF k 0.30, "
           f"6061 k 160 W/m K; 0.5 mm liner under the lid in both configurations; jacket RR-HD-S-131 (cap) covers {cov['cap_covered_m2']:.4f} of {cov['top_area_m2']:.4f} m2 of the top "
           f"({100 * cov['cap_fraction']:.0f} %: screw holes, keeper / latch cut-out uncovered) and RR-HD-S-132 covers {cov['front_band_m2']:.4f} of {cov['side_area_m2']:.4f} m2 of the "
           "side faces (front band; sides beside the side rails, rear face and underside are not insulated); 5 W electronics dissipation counted as heating; "
           "mount and cables 0.06 W/K. Heater = UA x (set-point - ambient) - 5 W.", "",
           _t(["Case", "UA (W/K)", "Heater at -20 C, set-point +5 C (W)", "Heater at -25 C, set-point +10 C (W)"],
              [(k, f"{v['UA_W_per_K']:.2f}", f"{v['heater_W_at_-20C_setpoint_+5C']:.1f}", f"{v['heater_W_at_-25C_setpoint_+10C']:.1f}") for k, v in th.items()]), "",
           "The jacket is part of the standard cold configuration (lead decision): required for operation below 0 C. Only a 0.5 mm liner fits inside the cover "
           "(0.9 mm cover clearance, 6.3 mm board height), so the jacket is external: cap top z 48.0 (ceiling 50), front band x 188.2..191.2 (envelope 212.5). "
           "The 30 W heater allocation (contract heater_peak_at_12v) is compared with the draught cases.", ""]
    md += ["## 10. Printed parts in print orientation (tool-checked: bounding box and downward-facing faces of the oriented solid)", "",
           "Downward faces = faces above the bed whose normal points more than 45 deg downward: each needs a bridge or support. Where the slicer "
           "will put supports and why they do not touch a critical surface is stated per part in `prototype/print_schedule.md`.", "",
           _t(["Part number", "Part", "Bounding box (mm)", "Fits", "Downward faces", "Area (mm2)", "Largest (z / span / length mm)"],
              [(x["pn"], x["part"], " x ".join(str(v) for v in x["bbox_print_mm"]), x["fits"], x.get("downward_faces", "-"), x.get("downward_area_mm2", "-"),
                "; ".join(f"{o['z']}/{o['span_mm']}/{o['length_mm']}" for o in x.get("largest_downward_faces", [])[:3])) for x in d["printed_parts"]]), ""]
    md += ["## 11. EMI bond points of the prototype fences (tool-checked clamping)", "",
           "; ".join(f"{k}: " + ", ".join(f"{v:+.1f}" for v in vals) for k, vals in d.get("bond_points", {}).items()), ""]
    (OUT / "head_report.md").write_text("\n".join(md))
